clear;
clc;
close all;

serviceAreaKm2 = 5;
radiiKm = [1.0 0.5];
usersPerCell = 30;

hexArea = @(R) (3 * sqrt(3) / 2) .* R.^2;

cellAreaKm2 = hexArea(radiiKm);
cellCount = ceil(serviceAreaKm2 ./ cellAreaKm2);
estimatedUsers = cellCount .* usersPerCell;

capacityTable = table( ...
    radiiKm(:), ...
    cellAreaKm2(:), ...
    cellCount(:), ...
    repmat(usersPerCell, numel(radiiKm), 1), ...
    estimatedUsers(:), ...
    'VariableNames', { ...
        'Radius_km', ...
        'CellArea_km2', ...
        'EstimatedCells', ...
        'UsersPerCell', ...
        'IllustrativeUsers'});

disp(capacityTable); %[output:8ee7d631]

R = radiiKm(1);

centers = [
     0,                  0;
     1.5*R,  sqrt(3)*R/2;
     1.5*R, -sqrt(3)*R/2;
     0,      sqrt(3)*R;
     0,     -sqrt(3)*R;
    -1.5*R,  sqrt(3)*R/2;
    -1.5*R, -sqrt(3)*R/2
];

theta = (0:6) * pi/3;

figure; %[output:6e24d4cb]
hold on; %[output:6e24d4cb]
axis equal; %[output:6e24d4cb]
grid on; %[output:6e24d4cb]

for k = 1:size(centers, 1)
    x = centers(k, 1) + R*cos(theta);
    y = centers(k, 2) + R*sin(theta);

    plot(x, y, 'k-'); %[output:6e24d4cb]

    text(centers(k, 1), centers(k, 2), ...
        sprintf('Cell %d', k), ...
        'HorizontalAlignment', 'center');
end

xlabel('x (km)'); %[output:6e24d4cb]
ylabel('y (km)'); %[output:6e24d4cb]
title('Idealized Seven-Cell Hexagonal Cluster'); %[output:6e24d4cb]

hold off; %[output:6e24d4cb]

mobileX = linspace(-0.2*R, 1.7*R, 300);
mobileY = zeros(size(mobileX));

d1 = hypot(mobileX, mobileY);
d2 = hypot(mobileX - 1.5*R, mobileY);


servingCell = ones(size(mobileX));
servingCell(d2 < d1) = 2;

handoffIndex = find(diff(servingCell) ~= 0, 1, 'first') + 1;

figure; %[output:70458fd8]
hold on; %[output:70458fd8]
grid on; %[output:70458fd8]

plot(mobileX, d1, 'LineWidth', 1.5); %[output:70458fd8]
plot(mobileX, d2, 'LineWidth', 1.5); %[output:70458fd8]

if ~isempty(handoffIndex)
    xline(mobileX(handoffIndex), '--r', 'Handoff decision'); %[output:70458fd8]
end

xlabel('Mobile x-position (km)'); %[output:70458fd8]
ylabel('Distance to cell center (km)'); %[output:70458fd8]

legend('Cell 1', 'Cell 2', 'Location', 'best'); %[output:70458fd8]
title('Nearest-Center Handoff Approximation'); %[output:70458fd8]

hold off; %[output:70458fd8]

figure; %[output:0292cbd1]

stairs(mobileX, servingCell, 'LineWidth', 1.5); %[output:0292cbd1]
grid on; %[output:0292cbd1]

xlabel('Mobile x-position (km)'); %[output:0292cbd1]
ylabel('Serving-cell ID'); %[output:0292cbd1]

title('Serving Cell Along the Mobile Path'); %[output:0292cbd1]

if ~isempty(handoffIndex) %[output:group:5a375c71]
    fprintf('Geometric handoff at x = %.3f km\n', ... %[output:815e389e]
        mobileX(handoffIndex)); %[output:815e389e]
end %[output:group:5a375c71]


